import re
from typing import Any


def od_rows(type_slug: str, q: str = "") -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    cursor: str | None = None
    for _ in range(100):
        if q:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor, q=q)
        else:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor)
        out.extend(page.get("records") or [])
        cursor = page.get("nextCursor")
        if not cursor:
            break
    return out


def od_data(row: Any) -> dict[str, Any]:
    return dict((row or {}).get("data") or {})


def od_text(value: Any) -> str:
    return str(value).strip() if value is not None else ""


def od_link_ids(row: Any, field: str) -> list[str]:
    out: list[str] = []
    for ref in ((row or {}).get("links") or {}).get(field) or []:
        if isinstance(ref, dict) and ref.get("id"):
            out.append(str(ref["id"]))
        elif isinstance(ref, str):
            out.append(ref)
    return out


import csv
import io

KINDS = {"products": "products", "customers": "customers", "addresses": "delivery addresses", "catalogue": "customer catalogue rows"}


def clean(row: dict[Any, Any]) -> dict[str, str]:
    return {od_text(k).lower().replace(" ", "_"): od_text(v) for k, v in row.items() if k is not None}


def read_table(path: str) -> list[dict[str, str]]:
    if path.lower().endswith((".xlsx", ".xlsm")):
        import openpyxl

        sheet = openpyxl.load_workbook(api.files.get(file=path, scope="agent"), data_only=True, read_only=True).worksheets[0]
        table = [["" if v is None else v for v in r] for r in sheet.iter_rows(values_only=True)]
        table = [r for r in table if any(od_text(v) for v in r)]
        if not table:
            return []
        return [clean(dict(zip(table[0], r))) for r in table[1:]]
    text = api.files.read(file=path, scope="agent")
    return [clean(r) for r in csv.DictReader(io.StringIO(text.lstrip("﻿")))]


def truthy(value: str) -> bool:
    return value.strip().lower() in ("true", "yes", "y", "1")


def number(value: str, fallback: float) -> float:
    try:
        return float(value)
    except ValueError:
        return fallback


def save(type_slug: str, known: dict[str, dict[str, Any]], key: str, title: str, data: dict[str, Any], links: dict[str, Any]) -> None:
    record: dict[str, Any] = {"title": title[:200], "data": data}
    if links:
        record["links"] = links
    if key in known:
        api.records.update(type_slug=type_slug, record_id=known[key]["id"], record=record)
    else:
        known[key] = api.records.create(type_slug=type_slug, record=record)


def mapping_key(d: dict[str, Any]) -> str:
    return "|".join([od_text(d.get("account_code")), od_text(d.get("customer_code")), od_text(d.get("customer_unit")), od_text(d.get("item_code")), od_text(d.get("customer_description")) if not od_text(d.get("customer_code")) else ""]).upper()


file_path = od_text(params.get("file_path"))
if not file_path:
    raise ValueError("file_path is required: the path of the list in the agent's files, for example Lists/products.csv")
rows = read_table(file_path)
columns: set[str] = set()
for row in rows[:1]:
    columns = set(row.keys())
list_kind = ""
if {"item_code", "account_code"} <= columns:
    list_kind = "catalogue"
elif {"item_code", "name"} <= columns:
    list_kind = "products"
elif {"label", "address"} <= columns:
    list_kind = "addresses"
elif {"account_code", "name"} <= columns:
    list_kind = "customers"
loaded = 0
skipped = 0
waiting = 0
linked = 0
if list_kind == "products":
    products: dict[str, dict[str, Any]] = {od_text(od_data(r).get("item_code")).upper(): r for r in od_rows("od_products")}
    for row in rows:
        code = row.get("item_code", "")
        if not code or not row.get("name"):
            skipped += 1
            continue
        data: dict[str, Any] = {"item_code": code, "sell_unit": row.get("sell_unit", "each") or "each", "category": row.get("category", ""), "active": truthy(row.get("active", "true") or "true")}
        if row.get("base_unit"):
            data["base_unit"] = row["base_unit"]
        if row.get("units_per_pack"):
            data["units_per_pack"] = number(row["units_per_pack"], 1)
        save("od_products", products, code.upper(), row["name"], data, {})
        loaded += 1
    for entry in od_rows("od_customer_catalogue"):
        item = od_text(od_data(entry).get("item_code")).upper()
        if item in products and not od_link_ids(entry, "product"):
            api.records.update(type_slug="od_customer_catalogue", record_id=entry["id"], record={"links": {"product": [products[item]["id"]]}})
            linked += 1
elif list_kind == "customers":
    profiles: dict[str, dict[str, Any]] = {od_text(od_data(r).get("account_code")).upper(): r for r in od_rows("od_customer_profiles")}
    for row in rows:
        code = row.get("account_code", "")
        if not code or not row.get("name"):
            skipped += 1
            continue
        save("od_customer_profiles", profiles, code.upper(), row["name"], {"account_code": code, "email_domain": row.get("email_domain", ""), "other_names": row.get("other_names", ""), "order_notes": row.get("order_notes", ""), "order_rules": row.get("order_rules", ""), "cutoff_time": row.get("cutoff_time", "")[:5], "po_required": truthy(row.get("po_required", "")), "auto_confirm": "never" if row.get("auto_confirm", "").lower() == "never" else "follow_default"}, {})
        loaded += 1
elif list_kind == "addresses":
    addresses: dict[str, dict[str, Any]] = {(od_text(od_data(r).get("account_code")) + "|" + od_text(r.get("title"))).upper(): r for r in od_rows("od_delivery_addresses")}
    for row in rows:
        if not row.get("label") or not row.get("address"):
            skipped += 1
            continue
        save("od_delivery_addresses", addresses, (row.get("account_code", "") + "|" + row["label"]).upper(), row["label"], {"account_code": row.get("account_code", ""), "address": row["address"], "site_code": row.get("site_code", ""), "is_default": truthy(row.get("is_default", ""))}, {})
        loaded += 1
elif list_kind == "catalogue":
    known_products: dict[str, dict[str, Any]] = {od_text(od_data(r).get("item_code")).upper(): r for r in od_rows("od_products")}
    catalogue: dict[str, dict[str, Any]] = {mapping_key(od_data(r)): r for r in od_rows("od_customer_catalogue")}
    for row in rows:
        account = row.get("account_code", "")
        item = row.get("item_code", "")
        if not account or not item:
            skipped += 1
            continue
        rounding = row.get("rounding", "none").lower()
        entry_data: dict[str, Any] = {"account_code": account, "customer_code": row.get("customer_code", ""), "customer_description": row.get("customer_description", ""), "customer_unit": row.get("customer_unit", ""), "item_code": item, "conversion_factor": number(row.get("conversion_factor", "1") or "1", 1), "rounding": rounding if rounding in ("none", "up", "down", "nearest") else "none", "source": "imported"}
        links: dict[str, Any] = {}
        if item.upper() in known_products:
            links = {"product": [known_products[item.upper()]["id"]]}
        else:
            waiting += 1
        save("od_customer_catalogue", catalogue, mapping_key(entry_data), account + " / " + (entry_data["customer_code"] or entry_data["customer_description"]) + " " + entry_data["customer_unit"], entry_data, links)
        loaded += 1
recognised = bool(list_kind)
if not recognised:
    result = "This file is not one of the four lists. The first row must hold the column names. Products need item_code and name. Customers need account_code and name. Delivery addresses need label and address. The customer catalogue needs account_code and item_code. This file has: " + (", ".join(sorted(columns)) or "no columns") + "."
else:
    result = "Loaded " + str(loaded) + " " + KINDS[list_kind] + "."
    if skipped:
        result += " Skipped " + str(skipped) + " rows with a required column left empty."
    if waiting:
        result += " " + str(waiting) + " of them name an item code that is not in the product list yet. They start working as soon as that product is loaded."
    if linked:
        result += " Connected " + str(linked) + " catalogue rows that were waiting for these products."
